insert into household (id, name, currency_code, ai_context_text) values
  ('e569cb3a-7223-4e05-90fa-46ea9596aa9b', 'Rivera Household', 'USD', 'Two-parent US household with one teenager. Fixed costs (housing, utilities, insurance, loan payments) are handled outside this budget; this plan covers discretionary spending and savings only. Approximate monthly amount available for discretionary spending plus savings is $3,200-$4,200, higher in September (back-to-school) and December (holidays). The family had almost no structured savings until recently, so the starting balance is modest. They want a $5,000 cushion by February 1, 2027 and prefer trading dining out for home cooking and bar nights for drinks at home rather than deep cuts. Groceries and savings have hard floors and should not be cut to zero. Both parents share the savings contribution.');
